        $quality['apps_without_navigation']=array_values(array_filter($appIds,fn($id)=>!count(array_filter($data['events'],fn($e)=>$e['app_id']===$id&&$e['type']==='section_open'))));$quality['forum_visibility_observations']=count(array_filter($events,fn($e)=>$e['event_type']==='forum_message_visible'));$opens=array_values(array_filter($events,fn($e)=>$e['event_type']==='forum_open'));$quality['visibility_supported_opens']=count(array_filter($opens,fn($e)=>$e['visibility_observer_available']===true));$quality['visibility_unsupported_opens']=count(array_filter($opens,fn($e)=>$e['visibility_observer_available']===false));$quality['visibility_support_unknown']=count(array_filter($opens,fn($e)=>$e['visibility_observer_available']===null));$quality['selected_posts']=count($messages);$quality['eligible_students']=count($nodes);$quality['valid_process_events']=count($individual);$quality['group_process_events']=count($groupProcess);$quality['scope_is_partial']=(int)(!empty($p['app_id'])||!empty($p['user_id']));$quality['capabilities']=['forum_message_visibility'=>true,'material_view_events'=>false,'post_edit_history'=>false,'automatic_icap'=>false];
        $publicFilters=$filters;if(isset($publicFilters['user_id']))$publicFilters['user_id']=self::participant($publicFilters['user_id']);
        $aiRows=[];foreach($data['messages'] as $m)if(isset($appsById[$m['app_id']])){$a=$appsById[$m['app_id']];$aiRows[]=['message_id'=>$m['id'],'app_id'=>$a['id'],'student_id'=>self::participant($a['user_id']),'role'=>$m['role'],'timestamp'=>$m['created_at'],'status'=>$m['status'],'body'=>$text?$m['content']:null];}
        $responses=[];foreach($apps as $a){$d=obj($a['draft']);$row=['app_id'=>$a['id'],'student_id'=>self::participant($a['user_id']),'case_id'=>$a['case_id'],'week_id'=>$settings[$a['case_id']]['week_id']??null,'group_id'=>$settings[$a['case_id']]['group_id']??null,'attempt_no'=>(int)$a['attempt_no'],'case_version_id'=>$a['version_id'],'response_mode'=>$a['response_mode'],'excluded'=>(int)$a['excluded'],'initial_at'=>$a['initial_at'],'submitted_at'=>$a['submitted_at']];foreach(['knowledge','confidence','difficulty','severity','final_confidence','final_difficulty','final_severity'] as $key)$row[$key]=$d[$key]??null;$row['reflection']=$text?($d['reflection']??null):null;$responses[]=$row;}
        $history=[];$versions=[];foreach($cases as $cid=>$case){foreach($db->all('SELECT id,case_id,revision,week_id,group_id,protocol_version,framework,reason,created_at FROM research_settings WHERE case_id=? ORDER BY revision',[$cid]) as $entry){$entry['framework']=$text?obj($entry['framework']):null;if(!$text)$entry['reason']=null;$history[]=$entry;}}foreach($data['case_versions'] as $version)if(isset($cases[$version['case_id']]))$versions[]=['case_version_id'=>$version['id'],'case_id'=>$version['case_id'],'version'=>(int)$version['version'],'created_at'=>$version['created_at'],'body'=>$text?$version['body']:null,'instructions'=>$text?$version['instructions']:null];
        $manifest=['schema_version'=>'vakalab-research-1','generated_at'=>now(),'study_design'=>'six-week case discussions; ICAP + SNA; optional sequence/process analyses','participant_ids'=>'stable pseudonyms; free-text is not automatically anonymized','edge_direction'=>'reply author -> parent-message author','edge_weight'=>'count of direct replies; self replies excluded from network edges, retained in reply_events','attempt_scope'=>!empty($p['app_id'])?'selected_application':$attempt,'phase'=>$phase?:'both','include_text'=>$text,'filters'=>$publicFilters,'phase_filter_applies_to'=>'forum messages and networks; process logs retain the full selected application','code_policy'=>'explicit consensus in highest coding round; disagreement stays blank; no inference from replies or visibility','sequence_units'=>['individual'=>'student + application attempt + phase','dialogue'=>'human-selected connected reply chain'],'process_units'=>['individual'=>'application attempt','group'=>'group_id + week_id'],'missingness'=>'blank code is unclassified, never Passive; unknown historical order/metadata remains flagged','source_document'=>'User-provided study plan, 20 November 2026'];
        return ['manifest'=>$manifest,'quality'=>$quality,'tables'=>['nodes'=>array_values($nodes),'roster'=>$roster,'cases'=>$caseRows,'case_versions'=>$versions,'settings_history'=>$history,'messages'=>$messages,'reply_events'=>$replyEvents,'edges'=>$edges,'annotations'=>$annotationRows,'coding_sheet'=>$codingSheet,'dialogues'=>$dialogueRows,'sequence_individual'=>$sequence,'sequence_dialogue'=>$dialogueSequence,'events_all'=>$events,'message_exposures'=>array_values(array_filter($events,fn($e)=>$e['event_type']==='forum_message_visible')),'ai_messages'=>$aiRows,'student_responses'=>$responses,'process_individual'=>$individual,'process_group'=>$groupProcess],'networks'=>$networks];
    }
    public static function graphml(array $network): string {
        $e=fn($v)=>htmlspecialchars((string)($v??''),ENT_XML1|ENT_QUOTES,'UTF-8');$xml='<?xml version="1.0" encoding="UTF-8"?><graphml xmlns="http://graphml.graphdrawing.org/xmlns"><key id="label" for="node" attr.name="label" attr.type="string"/><key id="weight" for="edge" attr.name="weight" attr.type="int"/>';
        foreach(['case_id','week_id','group_id','phase'] as $key)$xml.='<key id="'.$key.'" for="graph" attr.name="'.$key.'" attr.type="string"/>';$xml.='<graph id="'.$e($network['id']).'" edgedefault="directed">';foreach(['case_id','week_id','group_id','phase'] as $key)$xml.='<data key="'.$key.'">'.$e($network[$key]).'</data>';
        foreach($network['nodes'] as $n)$xml.='<node id="'.$e($n['Id']).'"><data key="label">'.$e($n['Label']).'</data></node>';foreach($network['edges'] as $edge)$xml.='<edge id="'.$e($edge['Id']).'" source="'.$e($edge['Source']).'" target="'.$e($edge['Target']).'"><data key="weight">'.(int)$edge['Weight'].'</data></edge>';return $xml.'</graph></graphml>';
    }
    public static function files(array $bundle): array {
        $files=['manifest.json'=>js($bundle['manifest']),'quality.json'=>js($bundle['quality']),'research-data.json'=>js($bundle),'README_TR.md'=>self::readme()];
        $headers=['nodes'=>['Id','Label'],'edges'=>['Id','Source','Target','Type','Weight','Layer','case_id','week_id','group_id','phase'],'roster'=>['student_id','case_id','week_id','group_id','currently_assigned'],'messages'=>['message_id','student_id','app_id','case_version_id','case_id','week_id','group_id','case_stage','timestamp','parent_message_id','thread_id','icap_code','coding_status','body'],'coding_sheet'=>['message_id','student_id','case_id','week_id','group_id','case_stage','parent_message_id','thread_id','body','coder_label','round_no','code','status','evidence','evidence_dialogue_id','interactive_reviewed'],'annotations'=>['id','post_id','dialogue_id','coder_label','round_no','code','status','evidence','supersedes_id','created_at'],'dialogues'=>['dialogue_id','case_id','case_stage','message_count','icap_code','coding_status'],'sequence_individual'=>['sequence_id','sequence_order','message_id','student_id','week_id','group_id','case_stage','icap_code','coding_status'],'sequence_dialogue'=>['dialogue_id','sequence_order','message_id','student_id','icap_code','dialogue_icap_code'],'events_all'=>['event_id','process_instance_id','student_id','case_id','week_id','group_id','case_stage','event_type','timestamp','received_at','timestamp_source'],'process_individual'=>['case:concept:name','concept:name','time:timestamp','org:resource','student_id','case_id','week_id','group_id'],'process_group'=>['case:concept:name','concept:name','time:timestamp','org:resource','student_id','case_id','week_id','group_id'],'message_exposures'=>['event_id','student_id','target_student_id','message_id','case_id','week_id','group_id','case_stage','timestamp','message_visible_ms','visibility_basis'],'ai_messages'=>['message_id','app_id','student_id','role','timestamp','status','body'],'student_responses'=>['app_id','student_id','case_id','week_id','group_id','attempt_no','initial_at','submitted_at','reflection'],'cases'=>['case_id','week_id','group_id','protocol_version','settings_revision'],'case_versions'=>['case_version_id','case_id','version','created_at','body','instructions'],'settings_history'=>['id','case_id','revision','week_id','group_id','protocol_version','framework','reason','created_at']];
        foreach($bundle['tables'] as $name=>$rows)$files[$name.'.csv']=self::csv($rows,$headers[$name]??null);
        foreach($bundle['networks'] as $n){$path='networks/'.$n['id'].'/';$files[$path.'nodes.csv']=self::csv($n['nodes'],['Id','Label']);$files[$path.'edges.csv']=self::csv($n['edges'],['Id','Source','Target','Type','Weight','Layer','case_id','week_id','group_id','phase']);$files[$path.'network.graphml']=self::graphml($n);}
        return $files;
    }
    private static function csv(array $rows,?array $headers=null): string {
        if($rows)return Export::csv($rows);$f=fopen('php://temp','w+');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,$headers?:['no_records'],',','"','');rewind($f);return stream_get_contents($f);
    }
    public static function zip(array $files,string $path): void {
        demand(class_exists('ZipArchive'),'ZIP uzantısı sunucuda kurulu olmalı',503);$zip=new ZipArchive();demand($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)===true,'Araştırma paketi hazırlanamadı',503);try{foreach($files as $name=>$bytes)demand($zip->addFromString($name,$bytes),'Paket dosyası eklenemedi',503);}finally{$zip->close();}
    }
    public static function readme(): string {return <<<'TEXT'
# VakaLab araştırma paketi

Gephi: Her networks/L-... klasörü tek vaka × hafta × grup × Önce/Sonra ağıdır. network.graphml dosyasını açın veya önce nodes.csv (Id, Label), ardından edges.csv (Source, Target, Directed, Weight) içe aktarın. Düğümler yalnız mesaj yazanlardan oluşmaz; seçilen kapsamdaki uygun atanmış katılımcılar da vardır. Böylece izole düğümler korunur. roster.csv güncel atama kapsamını gösterir; geçmiş grup üyeliği tahmin edilmez. Öğrenci/çalışma filtresi kullanılmışsa ağ kısmidir; kalite dosyasındaki scope_is_partial alanına bakın. Farklı aşamaları veya haftaları yanlışlıkla birleştirmemek için katman klasörlerini ayrı açın.

Yön: Yanıt yazan -> yanıt verilen mesajın yazarı. Ağırlık: doğrudan yanıt sayısı. Öz yanıtlar ağdan çıkarılır, reply_events.csv içinde korunur. Bu bir yanıt ağıdır; okuma veya bilişsel etkileşim ağı olduğu kendiliğinden varsayılamaz.

ICAP: messages.csv içerik analizi birimlerini; annotations.csv kodlayıcı, tur, durum, gerekçe ve değişiklik geçmişini içerir. Aynı kodlayıcının yeni kaydı eski kaydı supersedes_id ile izler. Diziler en yüksek kodlama turundaki açık uzlaşı kodlarını kullanır. Çatışma veya uzlaşı yoksa icap_code boştur. Bu boşluk Passive değildir. Interactive için bağlantılı, en az iki katılımcılı insan tanımlı diyalog ve karşılıklı fikir geliştirme incelemesi gerekir; bunlar yapısal koşullardır, sistem anlamsal doğrulama yapmaz. Diyalog kodu üyelerin mesaj kodlarına otomatik yayılmaz. Kodlayıcı etiketi dışarıda yapılmış kodlamanın araştırmacı tarafından aktarılmasını da destekler; kör ve bağımsız kodlayıcı çalışması otomatik varsayılmaz.

Sequence Analysis: sequence_individual.csv öğrenci × vaka denemesi × aşama içindeki kendi katkılarının dizisidir. sequence_dialogue.csv araştırmacının belirlediği bağlı diyalog sırasıdır. Başka öğrencinin hemen sonra mesaj yazması yanıt ilişkisi sayılmaz. Boş kodları düşürerek boşluğun iki yanını yapay biçimde birleştirmeyin. TraMineR için bu uzun tablo dizi tablosuna dönüştürülebilir; eksik durumları ve değişken dizi uzunluklarını açıkça ele alın. server_sequence yalnız yeni kayıtlarda vardır; eski eşzamanlı kayıtların UUID sırası nedensel sıra değildir.

Process Mining: process_individual.csv sütunları case:concept:name (öğrenci-vaka denemesi), concept:name (etkinlik), time:timestamp (UTC ISO 8601), org:resource (katılımcı) eşleştirmesiyle PM4Py'ye alınabilir. process_group.csv süreç örneği group_id + week_id'dir; grup/haftası bilinmeyen kayıtlar bu dosyaya konmaz. Pedagojik case_id ayrı özelliktir. actor_lane=ai satırları AI yanıtıdır; öğrenci davranışı olarak yorumlamayın. Tarayıcı ve sunucu saat kaynakları ayrı tutulur; bozuk zamanlı tarayıcı olayları hazır süreç dosyası dışında, events_all.csv içinde kalır. Gönderimler anlık olaydır; yazma/okuma süresi uydurulmaz. Geçmişte kaydedilmeyen materyal inceleme veya revizyon eylemleri üretilmez.

Kalite: quality.json ve manifest.json kapsamı, eksikleri, saat bağlarını, veri toplamaya sonradan eklenen özellikleri ve katmanları açıklar. Kodlar tamamlanmadan, eksik hafta/grup düzeltilmeden ve pilot kayıtları incelenmeden analizlerin hazır olduğu varsayılmaz. Aynı öğrencinin altı haftadaki mesajları bağımsız gözlemler sayılmamalıdır. Bu paket ölçümleri sağlar; otomatik istatistiksel anlamlılık veya nedensellik üretmez.

CSV dosyalarında elektronik tablo formül koruması uygulanır; özgün metni aynen incelemek için research-data.json kullanın.

Katılımcı kimlikleri kararlı araştırma kodlarıdır. Metinleri dahil ettiyseniz serbest metinde kişi/okul adı bulunmadığını ayrıca kontrol edin; otomatik tam anonimleştirme iddiası yoktur. Test/deneme/analiz dışı kayıtlar yalnız seçilmişse dahil edilir. Sürüm ve filtreler manifestte kayıtlıdır.
TEXT;
    }
}
